#include <bits/stdc++.h>
using namespace std;

int main() {

	int sum = 0;
	for(int i=0;i<6;i++){
		for(int j=i+1;j<=6;j++){
			for(int k=0;k<6;k++){
				for(int l=k+1;l<=6;l++){
					int h = j-i;
					int w = l-k;
					for(int m=2;m<=h*w;m++){
						sum += (h-1+w-1) * (m-1);
					}
				}
			}
		}
	}
	cout<<sum<<endl;

	return 0;
}
